document.querySelectorAll('[data-inbox-filters]').forEach(form=>{
  let timer;
  form.querySelectorAll('select,input[type="checkbox"]').forEach(control=>control.addEventListener('change',()=>form.requestSubmit()));
  const search=form.querySelector('input[name="q"]');
  search?.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>form.requestSubmit(),450);});
});
document.querySelectorAll('[data-app-status]').forEach(select=>{
  const canFinalize=select.dataset.canFinalize==='yes';
  const restrictTerminalOptions=status=>{
    if(canFinalize){
      if(!['hired','rejected','withdrawn'].includes(status)) return;
      [...select.options].forEach(option=>{option.hidden=option.value!==status&&!(status!=='withdrawn'&&option.value==='withdrawn');option.disabled=option.hidden;});
    } else {
      const allowed=['new','reviewing','interview','offered'];
      [...select.options].forEach(option=>{const keep=allowed.includes(status)?allowed.includes(option.value):option.value===status;option.hidden=!keep;option.disabled=!keep;});
    }
  };
  const original=select.dataset.originalStatus;
  select.value=original;restrictTerminalOptions(original);
  select.addEventListener('change',()=>restrictTerminalOptions(select.value));
});
let pendingAppForm=null,pendingReviewModal=null;
const confirmElement=document.getElementById('applicationStatusConfirm');
const confirmModal=confirmElement?bootstrap.Modal.getOrCreateInstance(confirmElement):null;
document.addEventListener('click',event=>{
  const save=event.target.closest('[data-confirm-application]');
  if(save){
    const form=document.getElementById(save.dataset.formId);if(!form)return;
    const status=form.querySelector('[data-app-status]');
    if(!status||status.value===status.dataset.originalStatus){form.requestSubmit();return;}
    pendingAppForm=form;pendingReviewModal=bootstrap.Modal.getOrCreateInstance(document.querySelector(save.dataset.reviewModal));
    pendingReviewModal.hide();window.setTimeout(()=>confirmModal?.show(),180);return;
  }
  if(event.target.closest('[data-confirm-submit]')&&pendingAppForm){confirmModal.hide();pendingAppForm.requestSubmit();pendingAppForm=null;return;}
  if(event.target.closest('[data-confirm-cancel]')&&pendingReviewModal){confirmModal.hide();window.setTimeout(()=>pendingReviewModal.show(),180);}
});
</script><?php require 'includes/footer.php'; ?>
